// Shared prefix of the "Entrada de teste" Code node.
// Manual Trigger supplies an empty item and therefore continues to the fixture below.
// P2 calls "Entrada interna P2" with EditorDispatch 1.1 built by backend/editor_dispatch.py.
const incoming = $input.first()?.json ?? {};
if (Object.keys(incoming).length) {
  const dispatch = incoming.dispatch ?? incoming;
  const object = v => v && typeof v === 'object' && !Array.isArray(v);
  const sha = v => typeof v === 'string' && /^[a-f0-9]{64}$/.test(v);
  const common = ['schema_version','kind','operation_id','route','creative_request','request_sha256','planning_sha256','policy','poll'];
  const routes = {
    transform: {required: ['payload','user_input','brief','ai','transform_source'], optional: ['asset_versions','layout_source','layout_sources','subtitle_source','subtitle_evidence','bookend_sources']},
    manual_sequence: {required: ['sequence_input'], optional: []},
    external_voice_intake: {required: ['voice_intake','ai'], optional: []},
  };
  if (!object(dispatch) || dispatch.schema_version !== '1.1' || dispatch.kind !== 'editor_dispatch') throw new Error('INVALID_EDITOR_DISPATCH: schema_version/kind (1.1)');
  const spec = routes[dispatch.route];
  if (!spec) throw new Error('INVALID_EDITOR_DISPATCH: route');
  const allowed = new Set([...common, ...spec.required, ...spec.optional]);
  const unknown = Object.keys(dispatch).filter(k => !allowed.has(k));
  if (unknown.length) throw new Error('INVALID_EDITOR_DISPATCH: campos fora da rota ' + dispatch.route + ': ' + unknown.join(','));
  const missing = [...common, ...spec.required].filter(k => dispatch[k] === undefined);
  if (missing.length) throw new Error('INVALID_EDITOR_DISPATCH: campos obrigatórios ausentes: ' + missing.join(','));
  if (typeof dispatch.operation_id !== 'string' || !dispatch.operation_id.trim() || dispatch.operation_id.length > 120) throw new Error('INVALID_EDITOR_DISPATCH: operation_id');
  if (!object(dispatch.creative_request) || dispatch.creative_request.schema_version !== '1.0') throw new Error('INVALID_EDITOR_DISPATCH: creative_request');
  if (!sha(dispatch.request_sha256) || !sha(dispatch.planning_sha256)) throw new Error('INVALID_EDITOR_DISPATCH: request/planning sha256');
  if (!object(dispatch.policy) || !Object.keys(dispatch.policy).length) throw new Error('INVALID_EDITOR_DISPATCH: policy');
  const p = dispatch.poll;
  if (!object(p) || Object.keys(p).sort().join(',') !== 'interval_seconds,max_attempts' || !Number.isInteger(p.max_attempts) || p.max_attempts < 1 || p.max_attempts > 240 || !(p.interval_seconds >= 1 && p.interval_seconds <= 30)) throw new Error('INVALID_EDITOR_DISPATCH: poll');
  if (dispatch.ai !== undefined) {
    const a = dispatch.ai;
    if (!object(a) || Object.keys(a).sort().join(',') !== 'art_model,content_model,transcription_model' || Object.values(a).some(v => typeof v !== 'string' || !v.trim() || v.length > 120)) throw new Error('INVALID_EDITOR_DISPATCH: ai');
  }
  for (const key of [...spec.required, ...spec.optional].filter(k => dispatch[k] !== undefined && !['layout_sources','bookend_sources'].includes(k))) {
    if (!object(dispatch[key])) throw new Error('INVALID_EDITOR_DISPATCH: ' + key);
  }
  for (const key of ['layout_sources','bookend_sources']) if (dispatch[key] !== undefined && !Array.isArray(dispatch[key])) throw new Error('INVALID_EDITOR_DISPATCH: ' + key);
  // Scene routes carry the compiler's own fingerprint; it must be the request P2 compiled.
  const compiled = dispatch.sequence_input ?? dispatch.voice_intake;
  if (compiled && (compiled.audit?.request_sha256 !== dispatch.request_sha256 || compiled.audit?.planning_sha256 !== dispatch.planning_sha256)) throw new Error('INVALID_EDITOR_DISPATCH: compiled input belongs to another request');
  return [{json: dispatch}];
}

