const validation=$input.first().json;
if(validation.valid!==true)throw new Error('Windmill recusou o contrato. Consulte Validar contrato.');
const route=$('Escolher rota de edicao').first().json.route;
const prepared=$(['manual_sequence','external_voice_intake'].includes(route)?'Montar sequencia manual':'Montar contrato da IA').first().json;
return [{json:{validation,...prepared}}];

const raw = $input.first().json.job_id;
const job_id = typeof raw === 'string' ? raw.trim().replace(/^"|"$/g, '') : '';
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(job_id)) throw new Error('Windmill não retornou um identificador válido.');
return [{json:{windmill_job_id:job_id,windmill_job_url:'https://wll.miabuilder.com/run/'+job_id+'?workspace=mia-micro-servicos'}}];

const job = $input.first().json;
const ctx = $('Identificar job').first().json;
const config = $('Entrada de teste').first().json;
const attempt = $runIndex + 1;
const completed = job.type === 'CompletedJob' || job.completed_at != null || typeof job.success === 'boolean';
// The engine's own code ([CODE] detail) reaches P2 first; generic code only when there is none (e.g. canceled).
const engine = /^\[([A-Z][A-Z0-9_]+)\]\s*([\s\S]*)$/.exec(String(job.result?.error?.message ?? ''));
if (job.canceled || job.is_canceled || (completed && job.success !== true)) throw new Error(engine ? engine[1]+': '+engine[2]+' '+ctx.windmill_job_url : 'RENDER_FAILED: renderização falhou ou foi cancelada. '+ctx.windmill_job_url);
if (!completed && attempt >= config.poll.max_attempts) throw new Error('RENDER_TIMEOUT: o job pode continuar no Windmill; não reenviar a renderização automaticamente. '+ctx.windmill_job_url);
return [{json:{...ctx,completed,attempt,result:completed ? job.result : null}}];

const item=$input.first().json;
const result=item.result;
if(!result?.output||!result.media) throw new Error('Resultado incompleto. Job: '+item.windmill_job_url);
const route=$('Escolher rota de edicao').first().json?.route??'transform';
// EditorResult 1.0: stable fields for P2/frontend; engine fields stay for audit compatibility.
const entry=$('Entrada de teste').first().json;
const operation=entry.operation_id?{operation_id:entry.operation_id,route,request_sha256:entry.request_sha256,planning_sha256:entry.planning_sha256}:null;
const artifacts={video:{...result.output,sha256:result.video_sha256??null,duration_seconds:result.media.duration_seconds,width:result.media.width,height:result.media.height},thumbnail:result.thumbnail??null,captions:result.captions??{}};
const envelope={schema_version:'1.0',kind:'editor_result',status:'completed',operation,artifacts,windmill_job_id:result.windmill_job_id??null};
if(['manual_sequence','external_voice_intake'].includes(route)){
 const prepared=$('Montar sequencia manual').first().json;
 return [{json:{windmill_job_url:item.windmill_job_url,...result,...envelope,editorial:{mode:'manual_sequence',voice_mode:prepared.manual_audit.voice_mode??'none',actual_seconds:result.media.duration_seconds,manual_audit:prepared.manual_audit,creative_decisions:prepared.creative_decisions,audio_enhancement:prepared.payload.edit.voice?.enhancement??'off'}}}];
}
const editorial=$('Montar contrato da IA').first().json;
// Directors plan the content; opening/closing seconds are fixed and excluded from the deviation.
const bookendSeconds=editorial.brief.bookend_seconds??0;
return [{json:{windmill_job_url:item.windmill_job_url,...result,...envelope,editorial:{brief:editorial.brief,content_plan:editorial.content_plan,review:editorial.editorial_review,creative_decisions:{...editorial.creative_decisions,duration:{...editorial.creative_decisions.duration,actual_seconds:result.media.duration_seconds,bookend_seconds:bookendSeconds,actual_content_seconds:result.media.duration_seconds-bookendSeconds,actual_deviation_seconds:result.media.duration_seconds-bookendSeconds-editorial.brief.target_duration_seconds,actual_deviation_percent:100*(result.media.duration_seconds-bookendSeconds-editorial.brief.target_duration_seconds)/editorial.brief.target_duration_seconds}},actual_seconds:result.media.duration_seconds,audio_enhancement:editorial.payload.edit.voice?.enhancement??editorial.payload.edit.audio?.enhancement??'off'}}}];

const envelope=$input.first().json;
const raw=envelope.asr??envelope;
const quality=envelope.asr_quality??null;
if(quality?.selected?.fatal?.length)throw new Error('ASR_REVIEW_REQUIRED: alinhamento inválido após tentativa limitada. '+quality.selected.fatal.join(', '));
const evidence = $('Preparar evidencias').first().json;
const duration = evidence.media?.duration_seconds;
if (!Number.isFinite(duration) || !Array.isArray(evidence.frames) || evidence.frames.length !== 6) throw new Error('Evidências ausentes ou incompletas.');
if (!raw || raw.error || !Array.isArray(raw.segments) || !Array.isArray(raw.words)) throw new Error('ASR não retornou segmentos e palavras com timestamps. Não estimar tempos por IA.');
const finiteRange = x => Number.isFinite(x.start) && Number.isFinite(x.end) && x.start >= 0 && x.end > x.start && x.end <= duration + 0.15;
const rawWords = raw.words.map(w => ({start:w.start,end:w.end,text:String(w.word ?? w.text ?? '').trim(),...(Number.isFinite(w.confidence)&&w.confidence>=0&&w.confidence<=1?{confidence:w.confidence}:{})})).filter(w => w.text);
if (rawWords.some(w => !Number.isFinite(w.start) || !Number.isFinite(w.end) || w.start<0 || w.end<w.start || w.end>duration+1 || w.start>duration+1)) throw new Error('Timestamps de palavras inválidos.');
const paddingAdjusted=rawWords.some(w=>w.end>duration)||raw.segments.some(s=>s.end>duration);
// Whisper also returns real words with start = end (95 of 975 in n8n 995022); they stay, and the caption compiler
// ends each one where the next word starts. Punctuation and MP3 padding clamped onto the last instant are dropped.
const words = rawWords.map(w=>({...w,start:Math.min(w.start,duration),end:Math.min(w.end,duration)})).filter(w=>w.end>w.start||(w.end===w.start&&w.start<duration&&/[\p{L}\p{N}]/u.test(w.text)));
const overlappingWords=words.some((w,i)=>i>0 && w.start<words[i-1].end-0.000001);
const segments = raw.segments.map((s,id)=>({id,start:s.start,end:Math.min(s.end,duration),text:String(s.text ?? '').trim(),no_speech_prob:s.no_speech_prob ?? null})).filter(s=>s.text);
if (!segments.length || segments.some(s=>!finiteRange(s))) throw new Error('Segmentos de transcrição inválidos.');
const flagged=new Map();
for(const issue of quality?.selected?.issues??[]){if(!flagged.has(issue.segment_id))flagged.set(issue.segment_id,[]);flagged.get(issue.segment_id).push(issue.code);}
for(let i=1;i<segments.length;i++){
 const previous=segments[i-1],current=segments[i];
 if(current.start<previous.end-0.000001)for(const id of [previous.id,current.id]){
  if(!flagged.has(id))flagged.set(id,[]);
  if(!flagged.get(id).includes('OVERLAPPING_SEGMENTS'))flagged.get(id).push('OVERLAPPING_SEGMENTS');
 }
}
for(const [index,s]of segments.entries()){
 const after=segments[index+1];
 const punctuationContinuation=/[,;:]\s*$/u.test(s.text)||/(?:^|\s)(e|ou|mas|porque|então|por exemplo)[\s,.!?…]*$/iu.test(s.text);
 const linkedContinuation=!/[.!?…]\s*$/u.test(s.text)&&after&&after.start-s.end<=1&&/^\p{Ll}/u.test(after.text);
 s.asr_issues=flagged.get(s.id)??[];
 s.end_candidate=!(punctuationContinuation||linkedContinuation);
 s.tail_gap_seconds=Math.max(0,(after?.start??duration)-s.end);
 s.requires_question_context=/^(?:não necessariamente\b|(?:sim|não)[,.!?](?:\s|$))/iu.test(s.text);
 // Restrict the hint to a subordinate opening, preserving questions/exclamations.
 s.requires_previous_context=!/[?!]\s*$/u.test(s.text)&&/^que\s+(?:o|a|os|as|um|uma|ele|ela|eles|elas)\b/iu.test(s.text.trim());
}
return [{json:{media:evidence.media,transcript:{text:String(raw.text||segments.map(s=>s.text).join(' ')),segments,words,quality_audit:quality,timing_basis:'asr_segments',warnings:[...(flagged.size?['ASR mantém segmentos suspeitos; seleção automática não pode usá-los sem revisão.']:[]),...(overlappingWords ? ['ASR trouxe palavras sobrepostas; esta integração usa legendas por segmento, sem destaque por palavra.'] : []),...(rawWords.length!==words.length ? ['ASR retornou palavras sem duração; cortes e legendas usam segmentos reais, sem estimar tempos.'] : []),...(paddingAdjusted ? ['Timestamps finais do ASR limitados à duração real da mídia (padding de até 1 s).'] : [])]},usage:raw.usage ?? null}}];

// BEGIN decision-report guard (kept identical in both director validators)
function validateDecisionReport(report, allowedIds, allowedFrames, requiredTopics) {
 const text=v=>typeof v==='string'&&v.trim().length>0&&v.length<=800;
 const keys=(o,ks)=>o&&typeof o==='object'&&!Array.isArray(o)&&Object.keys(o).length===ks.length&&ks.every(k=>Object.hasOwn(o,k));
 if(!keys(report,['summary','decisions','duration','limitations'])||!text(report.summary)||!Array.isArray(report.decisions)||report.decisions.length<1||report.decisions.length>12||!keys(report.duration,['reason','shorter_alternative','tradeoff'])||!Object.values(report.duration).every(text)||!Array.isArray(report.limitations)||report.limitations.length>12||!report.limitations.every(text)) throw new Error('Relatório de decisões criativas ausente ou inválido.');
 const topics=new Set();
 for(const d of report.decisions){
  if(!keys(d,['topic','choice','reason','segment_ids','frame_times'])||!text(d.topic)||d.topic.length>80||topics.has(d.topic)||!text(d.choice)||!text(d.reason)||!Array.isArray(d.segment_ids)||d.segment_ids.length>100||new Set(d.segment_ids).size!==d.segment_ids.length||d.segment_ids.some(id=>!Number.isInteger(id)||!allowedIds.has(id))||!Array.isArray(d.frame_times)||d.frame_times.length>6||new Set(d.frame_times).size!==d.frame_times.length||d.frame_times.some(t=>!Number.isFinite(t)||!allowedFrames.has(t))) throw new Error('Decisão com evidência inexistente, fora do contexto ou campos inválidos.');
  topics.add(d.topic);
 }
 const missingTopics=requiredTopics.filter(t=>!topics.has(t));
 if(missingTopics.length) throw new Error('Relatório sem decisões obrigatórias: '+missingTopics.join(', ')+'.');
 return report;
}
// END decision-report guard
// BEGIN art request builder
function buildArtRequest(context,capabilities,brief,orientation,evidence,config){
 if(!capabilities?.edit_schema)throw new Error("EDITOR_CAPABILITIES_REQUIRED: art request");
 const editSchema=JSON.parse(JSON.stringify(capabilities.edit_schema)); const limits=context.ending_constraints; for(const [key,max]of [['audio_fade_out_seconds',limits.max_audio_fade_out_seconds],['video_fade_out_seconds',limits.max_video_fade_out_seconds]]) editSchema.properties.ending.properties[key].maximum=Math.min(editSchema.properties.ending.properties[key].maximum??max,max);const pref=brief.preferences;
// Caption text and timing are compiled exclusively from the selected ASR segments.
// The art director controls presentation through preferences, never caption data.
editSchema.properties.captions=false;
if(pref){
 editSchema.properties.canvas={const:pref.canvas};
 editSchema.properties.orientation={const:orientation.orientation};
 editSchema.properties.audio={type:'object',additionalProperties:false,properties:{enhancement:{const:pref.voice.enhancement},gain_db:{const:pref.voice.gain_db}},required:['enhancement','gain_db']};
 editSchema.required=[...new Set([...editSchema.required,'audio','orientation'])];
 if(pref.layout?.name==='auto'){
  const allowed=pref.layout.options.map(x=>x.name),secondary=pref.layout.secondary_asset_ids;
  const single={type:'object',additionalProperties:false,properties:{layout:{const:'single'}},required:['layout']};
  const composite={type:'object',additionalProperties:false,properties:{layout:{enum:allowed.filter(x=>x!=='single')},secondary_asset_id:{enum:secondary}},required:['layout','secondary_asset_id']};
  editSchema.properties.composition={oneOf:[single,...(composite.properties.layout.enum.length&&secondary.length?[composite]:[])]};
  editSchema.required=[...new Set([...editSchema.required,'composition'])];
 }else editSchema.properties.composition=false;
 if(pref.photography.mode!=='auto'){
  if(pref.photography.mode==='off')editSchema.properties.color=false;
  else{const {mode,...color}=pref.photography;editSchema.properties.color={const:color};editSchema.required.push('color');}
  editSchema.properties.clips.items.properties.color=false;
 }
 if(pref.ending.mode==='none')editSchema.properties.ending=false;
 if(pref.ending.mode==='manual'){const {mode,...ending}=pref.ending;editSchema.properties.ending={const:ending};editSchema.required.push('ending');}
 if(pref.framing.mode==='manual'){editSchema.properties.clips.items.properties.crop={const:pref.framing.crop};editSchema.properties.clips.items.required=[...new Set([...editSchema.properties.clips.items.required,'crop'])];}
 editSchema.properties.clips.items.properties.transition_after={type:'object',additionalProperties:false,properties:{type:{const:'cut'},duration:{const:0},audio:false},required:['type']};
}
return { orientation_assessment: orientation, brief: brief, content_plan: context.content_plan, editorial_context: context.editorial_context, duration_audit: context.duration_audit, ending_constraints: context.ending_constraints, media: evidence.media, frame_times: evidence.frames.map(f=>f.time), asset_catalog: config.payload.edit.assets.concat((config.layout_sources??[]).map(x=>({id:x.asset_id,type:x.type,source:x.source,label:'Candidato visual autorizado'})),brief.music.mode === 'generate' ? [{ id: 'generated_music', type: 'audio', source: { key: 'video-editor/pending/generated-music' }, label: 'Trilha a gerar, 30 segundos' }] : []), edit_schema: editSchema, transition_catalog: capabilities.transition_catalog,...(pref?.layout?.name==='auto'?{automatic_layout_policy:{choice_format:'layout=<layout>;secondary=<asset_id|none>',visual_evidence_required:true,allowed_layouts:pref.layout.options.map(x=>x.name),allowed_secondary_asset_ids:pref.layout.secondary_asset_ids}}:{}) };
}

// END art request builder
const raw=$input.first().json;
let plan=raw.output ?? raw.text ?? raw;
if(typeof plan==='string') plan=JSON.parse(plan.replace(/^\x60\x60\x60(?:json)?\s*/,'').replace(/\s*\x60\x60\x60$/,''));
if(plan&&Object.keys(plan).length===1&&Array.isArray(plan.data)&&plan.data.length===1)plan=plan.data[0];
const source=$('Normalizar transcricao').first().json;
const config=$('Entrada de teste').first().json;
const brief=$('Normalizar briefing').first().json.brief;
if(!plan||plan.schema_version!=='1.2'||!['ready','message_not_found','review_required'].includes(plan.status)||typeof plan.main_message!=='string'||typeof plan.summary!=='string'||!Array.isArray(plan.clips)||plan.clips.length>6||!Array.isArray(plan.warnings)||plan.warnings.some(w=>typeof w!=='string')) throw new Error('Plano editorial inválido.');
if(Object.keys(plan).some(k=>!['schema_version','status','main_message','summary','clips','quality','warnings','decision_report'].includes(k))) throw new Error('Campo editorial desconhecido.');
// Content has not received a measured final timeline: duration numbers belong to backend.
const durationDecision=plan.decision_report?.decisions?.find(d=>d.topic==='duration');
if(durationDecision && durationDecision.choice!=='calculated_by_backend') throw new Error('Estimativa de duração não autorizada no relatório de conteúdo: use calculated_by_backend; valores reais são calculados pelo backend.');
const q=plan.quality;
if(!q||typeof q.opening_complete!=='boolean'||typeof q.ending_complete!=='boolean'||typeof q.message_supported!=='boolean'||typeof q.reason!=='string') throw new Error('Revisão editorial ausente.');
const evidenceIds=new Set(source.transcript.segments.filter(s=>plan.clips.some(c=>s.id>=c.start_segment_id&&s.id<=c.end_segment_id)).map(s=>s.id));
if(plan.status!=='ready'){
  validateDecisionReport(plan.decision_report,new Set(),new Set(),['selection','duration']);
  if(plan.clips.length) throw new Error('Plano não aprovado não pode conter recortes executáveis.');
  return [{json:{content_plan:plan,duration_seconds:0,brief,editorial_attempt:$runIndex+1,content_validation:{accepted:true,failures:[]}}}];
}
if(!plan.clips.length||!plan.main_message.trim()) throw new Error('Conteúdo marcado pronto sem mensagem ou fechamento completos.');
const segments=new Map(source.transcript.segments.map(s=>[s.id,s]));
const clips=plan.clips.map(c=>{
  if(Object.keys(c).some(k=>!['start_segment_id','end_segment_id','reason','pre_roll_seconds','post_roll_seconds'].includes(k))||!Number.isInteger(c.start_segment_id)||!Number.isInteger(c.end_segment_id)||c.end_segment_id<c.start_segment_id||typeof c.reason!=='string') throw new Error('Referência de segmento inválida.');
  for(const k of ['pre_roll_seconds','post_roll_seconds']) if(c[k]!=null && (!Number.isFinite(c[k])||c[k]<0||c[k]>1.5)) throw new Error('Margem de corte inválida.');
  const first=segments.get(c.start_segment_id),last=segments.get(c.end_segment_id);
  if(!first||!last) throw new Error('Segmento inexistente.');
  const firstIndex=source.transcript.segments.findIndex(s=>s.id===first.id),lastIndex=source.transcript.segments.findIndex(s=>s.id===last.id);
  const before=source.transcript.segments[firstIndex-1];
  const after=source.transcript.segments[lastIndex+1];
