function validateTransformPreferences(value,config){
 validatePreferenceSchema(transformPreferenceSchema,value);
 if(value.orientation?.mode==='auto'&&value.orientation.mirror_horizontal)throw new Error('INVALID_PREFERENCE: mirror requires manual orientation in this route');
 const crop=value.framing.crop;if(crop&&(crop.width<=0||crop.height<=0||crop.x+crop.width>1||crop.y+crop.height>1))throw new Error('INVALID_PREFERENCE: crop bounds');
 const b=config.transform_source;
 if(!b||Object.keys(b).some(k=>!['asset_id','version','sha256'].includes(k))||typeof b.asset_id!=='string'||!/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/.test(b.asset_id)||!Number.isInteger(b.version)||b.version<1||!/^[a-f0-9]{64}$/.test(b.sha256))throw new Error('SOURCE_BINDING_REQUIRED: trusted immutable working version');
 const captionAsset=value.captions.enabled&&value.captions.source?.mode==='asset';
 if(captionAsset){
  const s=config.subtitle_source,e=config.subtitle_evidence,ref=value.captions.source.asset;
  if(!s||s.asset_id!==ref.asset_id||s.version!==ref.version||!['srt','vtt','ass'].includes(s.format)||!/^[a-f0-9]{64}$/.test(s.sha256)||!s.source||Object.keys(s.source).length!==1||!['key','url'].includes(Object.keys(s.source)[0]))throw new Error('SUBTITLE_BINDING_REQUIRED: trusted immutable subtitle source');
  if(!e||e.kind!=='subtitle_evidence'||e.asset_id!==s.asset_id||e.version!==s.version||e.sha256!==s.sha256||e.format!==s.format||e.timing_basis!=='timeline'||!/^[a-f0-9]{64}$/.test(e.evidence_sha256)||!Array.isArray(e.segments)||!e.segments.length)throw new Error('SUBTITLE_EVIDENCE_REQUIRED: validated Windmill subtitle cues');
 }
 const layout=value.layout;
 if(layout){
  const validBinding=(secondary,id)=>secondary&&Object.keys(secondary).every(k=>['asset_id','type','source','version','sha256'].includes(k))&&secondary.asset_id===id&&['image','video'].includes(secondary.type)&&Number.isInteger(secondary.version)&&secondary.version>=1&&/^[a-f0-9]{64}$/.test(secondary.sha256)&&secondary.source&&typeof secondary.source==='object'&&!Array.isArray(secondary.source)&&Object.keys(secondary.source).length===1&&['key','url'].includes(Object.keys(secondary.source)[0])&&typeof Object.values(secondary.source)[0]==='string'&&Object.values(secondary.source)[0];
  const secondary=config.layout_source;
  if(layout.name==='auto'){
   if(secondary!==undefined)throw new Error('INVALID_PREFERENCE: automatic layout uses candidate bindings');
   const bindings=config.layout_sources;
   if(!Array.isArray(bindings)||bindings.length!==layout.secondary_asset_ids.length||new Set(bindings.map(x=>x.asset_id)).size!==bindings.length||layout.secondary_asset_ids.some(id=>!validBinding(bindings.find(x=>x.asset_id===id),id)))throw new Error('SOURCE_BINDING_REQUIRED: trusted automatic layout candidates');
  }else if(layout.name==='single'){
   if(secondary!==undefined)throw new Error('INVALID_PREFERENCE: single layout has no secondary source');
  }else{
   if(!validBinding(secondary,'layout_secondary'))throw new Error('SOURCE_BINDING_REQUIRED: trusted immutable secondary version');
  }
 }
 // Opening/closing media are immutable backend bindings named only by their slot.
 const bookendBindings=config.bookend_sources??[];
 const media=Object.entries(value.bookends??{}).filter(([,b])=>b.type!=='text');
 if(!Array.isArray(bookendBindings)||bookendBindings.length!==media.length||media.some(([kind,b])=>{const s=bookendBindings.find(x=>x.asset_id===b.asset_id);return !s||s.asset_id!=='bookend_'+kind||s.type!==b.type||Object.keys(s).some(k=>!['asset_id','type','source','version','sha256'].includes(k))||!Number.isInteger(s.version)||s.version<1||!/^[a-f0-9]{64}$/.test(s.sha256)||!s.source||typeof s.source!=='object'||Object.keys(s.source).length!==1||!['key','url'].includes(Object.keys(s.source)[0])||typeof Object.values(s.source)[0]!=='string';}))throw new Error('SOURCE_BINDING_REQUIRED: trusted immutable opening/closing media');
 if(value.canvas.width> (config.policy.max_width??1920)||value.canvas.height>(config.policy.max_height??1920))throw new Error('INVALID_PREFERENCE: canvas exceeds policy');
 return JSON.parse(JSON.stringify(value));
}

// END transform preference helpers
const config=$input.first().json;
const input=config.user_input ?? {};
if(!input || typeof input!=='object' || Array.isArray(input)) throw new Error('user_input deve ser um objeto.');
if(Object.keys(input).some(k=>!['main_message','target_duration_seconds','music','audio_enhancement','preferences'].includes(k))) throw new Error('Campo desconhecido no briefing do usuário.');
if(input.main_message!=null && typeof input.main_message!=='string') throw new Error('main_message deve ser texto ou null.');
const main_message=input.main_message?.trim() || null;
if(main_message && main_message.length>1000) throw new Error('main_message excede 1000 caracteres.');
if(input.preferences!==undefined&&input.target_duration_seconds===undefined)throw new Error('TRANSFORM_ROUTE_NOT_SUPPORTED: explicit suggested duration required');
const target=input.target_duration_seconds ?? config.brief?.target_duration_seconds ?? config.brief?.target_seconds ?? 45;
if(!Number.isFinite(target) || target<=0 || target>3600) throw new Error('Duração sugerida inválida.');
if(input.audio_enhancement!==undefined && !['off','voice_focus','neural_moderate'].includes(input.audio_enhancement)) throw new Error('Perfil de voz inválido.');
const preferences=input.preferences===undefined?null:validateTransformPreferences(input.preferences,config);
if(preferences&&input.audio_enhancement!==undefined&&input.audio_enhancement!==preferences.voice.enhancement)throw new Error('CONFLICTING_PREFERENCE: voice enhancement');
const audio_enhancement=preferences?.voice.enhancement ?? input.audio_enhancement ?? config.brief?.audio_enhancement ?? 'neural_moderate';
if(!['off','voice_focus','neural_moderate'].includes(audio_enhancement)) throw new Error('Perfil de voz inválido.');
const music=input.music ?? {mode:'none'};
if(!music||typeof music!=='object'||Array.isArray(music)||!['none','asset','generate'].includes(music.mode)||Object.keys(music).some(k=>!['mode','asset_id','prompt'].includes(k))) throw new Error('Configuração de trilha inválida.');
if(music.prompt!=null && (typeof music.prompt!=='string'||music.prompt.length>1000)) throw new Error('Prompt de trilha inválido.');
if(music.mode==='asset' && !config.payload.edit.assets.some(a=>a.id===music.asset_id&&a.type==='audio')) throw new Error('Trilha enviada não existe no catálogo autorizado.');
if(preferences&&music.mode==='generate')throw new Error('TRANSFORM_ROUTE_NOT_SUPPORTED: generated music needs a versioned stored asset; use an existing authorized track');
if(preferences&&music.mode==='asset'){const b=config.asset_versions?.[music.asset_id];if(!b||!Number.isInteger(b.version)||b.version<1||!/^[a-f0-9]{64}$/.test(b.sha256))throw new Error('SOURCE_BINDING_REQUIRED: music asset version/hash');}
if(preferences&&((music.mode==='asset')!==Object.hasOwn(preferences,'music')))throw new Error('INVALID_PREFERENCE: fixed music settings required exactly for the requested asset');
const {target_seconds,...base}=config.brief ?? {};
return [{json:{brief:{...base,music,audio_enhancement,...(preferences?{preferences,aspect_ratio:preferences.canvas.width+":"+preferences.canvas.height}:{}),mode:main_message?'user_guided':'automatic',main_message,target_duration_seconds:target,duration_is_suggestion:true,hard_max_seconds:config.policy.max_output_seconds}}}];

const data=$input.first().json;
const entry=$('Entrada de teste').first().json;
const operation=entry.operation_id?{operation_id:entry.operation_id,route:'transform',request_sha256:entry.request_sha256,planning_sha256:entry.planning_sha256}:null;
return [{json:{schema_version:'1.0',kind:'editor_result',operation,artifacts:null,status:data.content_plan.status,requested_main_message:data.brief.main_message,main_message:data.content_plan.main_message,warnings:data.content_plan.warnings,reason:data.content_plan.quality.reason,creative_decisions:{schema_version:'1.0',status:data.content_plan.status,content:data.content_plan.decision_report,art:null},rendered:false}}];

// BEGIN decision-report guard (kept identical in both director validators)
function validateDecisionReport(report, allowedIds, allowedFrames, requiredTopics) {
 const text=v=>typeof v==='string'&&v.trim().length>0&&v.length<=800;
 const keys=(o,ks)=>o&&typeof o==='object'&&!Array.isArray(o)&&Object.keys(o).length===ks.length&&ks.every(k=>Object.hasOwn(o,k));
 if(!keys(report,['summary','decisions','duration','limitations'])||!text(report.summary)||!Array.isArray(report.decisions)||report.decisions.length<1||report.decisions.length>12||!keys(report.duration,['reason','shorter_alternative','tradeoff'])||!Object.values(report.duration).every(text)||!Array.isArray(report.limitations)||report.limitations.length>12||!report.limitations.every(text)) throw new Error('Relatório de decisões criativas ausente ou inválido.');
 const topics=new Set();
 for(const d of report.decisions){
  if(!keys(d,['topic','choice','reason','segment_ids','frame_times'])||!text(d.topic)||d.topic.length>80||topics.has(d.topic)||!text(d.choice)||!text(d.reason)||!Array.isArray(d.segment_ids)||d.segment_ids.length>100||new Set(d.segment_ids).size!==d.segment_ids.length||d.segment_ids.some(id=>!Number.isInteger(id)||!allowedIds.has(id))||!Array.isArray(d.frame_times)||d.frame_times.length>6||new Set(d.frame_times).size!==d.frame_times.length||d.frame_times.some(t=>!Number.isFinite(t)||!allowedFrames.has(t))) throw new Error('Decisão com evidência inexistente, fora do contexto ou campos inválidos.');
  topics.add(d.topic);
 }
 const missingTopics=requiredTopics.filter(t=>!topics.has(t));
 if(missingTopics.length) throw new Error('Relatório sem decisões obrigatórias: '+missingTopics.join(', ')+'.');
 return report;
}
// END decision-report guard
// BEGIN transform choices guard
// The art director proposes; the user's fixed choices are materialized here, so a placeholder or a value the
// model did not copy never fails the edit (photography already works this way). Real P2 runs: 985108
// ("captions": false, "composition": false) and 994847 (fixed music fade-in changed).
function normalizeArtEdit(pref,edit){
 if(!edit||typeof edit!=='object'||Array.isArray(edit))return edit;
 for(const key of ['captions','composition']){
  const v=edit[key];
  if(v===false||v===null||(v&&typeof v==='object'&&!Array.isArray(v)&&!Object.keys(v).length))delete edit[key];
 }
 if(pref?.music&&Array.isArray(edit.audio_tracks)&&edit.audio_tracks.length===1){
  const t=edit.audio_tracks[0];
  for(const k of ['gain_db','loop','fade_in_seconds','fade_out_seconds'])t[k]=pref.music[k];
  t.start=0;
  if(!pref.music.ducking)delete t.ducking;
 }
 return edit;
}

function assertTransformChoices(pref,edit){
 if(!pref||!edit)return;
 const same=(a,b)=>JSON.stringify(a,Object.keys(a??{}).sort())===JSON.stringify(b,Object.keys(b??{}).sort());
 const deny=field=>{throw new Error('MANUAL_PREFERENCE_CHANGED: '+field);};
 if(!same(edit.canvas,pref.canvas))deny('canvas');
 const composition=edit.composition;
 if(pref.layout?.name==='auto'){
  if(!composition||typeof composition!=='object'||Array.isArray(composition))deny('automatic layout decision required');
  const option=pref.layout.options.find(x=>x.name===composition.layout);
  if(!option)deny('automatic layout outside authorized options');
  const keys=Object.keys(composition).sort();
  if(composition.layout==='single'){
   if(JSON.stringify(keys)!==JSON.stringify(['layout']))deny('single layout decision');
  }else if(JSON.stringify(keys)!==JSON.stringify(['layout','secondary_asset_id'])||!pref.layout.secondary_asset_ids.includes(composition.secondary_asset_id))deny('automatic secondary source');
 }else if(composition&&Object.keys(composition).length)deny('fixed layout');
 if(edit.audio?.mute||edit.audio?.denoise||edit.audio?.gain_db!==pref.voice.gain_db||edit.audio?.enhancement!==pref.voice.enhancement)deny('voice');
 const effects=(edit.clips??[]).map((c,i)=>({i,t:c.transition_after})).filter(x=>x.t&&x.t.type!=='cut');
 if(pref.transitions==='none'||!pref.transition_rules){if(effects.length)deny('transitions: cuts requested');}
 else for(const {i,t}of effects){
  if(i===edit.clips.length-1)deny('transition after the last clip');
  if(!pref.transition_rules.types.includes(t.type)||!(t.duration>0)||t.duration>pref.transition_rules.max_seconds+1e-9)deny('transition outside '+pref.transitions+' rules: '+t.type);
 }
 if(pref.preserve_source_order&&(edit.clips??[]).some((c,i,a)=>i&&c.source_in<a[i-1].source_out))deny('source order');
 if(pref.framing.mode==='manual'&&(edit.clips??[]).some(c=>!same(c.crop,pref.framing.crop)))deny('crop');
 // Fixed photography is materialized from preferences by the compiler. Model
 // suggestions are ignored instead of turning harmless non-determinism into a retry.
 if(pref.music){
  const tracks=edit.audio_tracks??[];if(tracks.length!==1)deny('one requested soundtrack');
  const t=tracks[0];for(const k of ['gain_db','loop','fade_in_seconds','fade_out_seconds'])if(t[k]!==pref.music[k])deny('music '+k);
  // Ducking on needs the director's numeric ducking object; it cannot be materialized from a boolean.
  if(Boolean(t.ducking)!==pref.music.ducking||t.start!==0)deny('music ducking/start');
 }
 if(pref.ending.mode==='none'&&Object.keys(edit.ending??{}).length)deny('ending off');
 if(pref.ending.mode==='manual'&&!same(edit.ending,Object.fromEntries(Object.entries(pref.ending).filter(([k])=>k!=='mode'))))deny('ending');
 if(pref.ending.mode==='soft'&&(!edit.ending||!(edit.ending.audio_fade_out_seconds>0)||!(edit.ending.video_fade_out_seconds>0)))deny('soft ending needs explicit fades within the approved tail');
}

function validateAutomaticLayoutAudit(pref,edit,report){
 if(pref?.layout?.name!=='auto'||!edit)return;
 const decision=report?.decisions?.find(x=>x.topic==='composition');
 const selected=edit.composition;
 const expected='layout='+selected.layout+';secondary='+(selected.secondary_asset_id??'none');
 if(!decision||decision.choice!==expected||!Array.isArray(decision.frame_times)||decision.frame_times.length<1)throw new Error('AUTOMATIC_LAYOUT_AUDIT_REQUIRED: composition choice must match the selected authorized layout and cite visual evidence');
}

// END transform choices guard
const input=$input.first().json;
let response=input.output??input.text??input;
if(typeof response==='string') response=JSON.parse(response.replace(/^\x60\x60\x60(?:json)?\s*/,'').replace(/\s*\x60\x60\x60$/,''));
const validated=$('Validar plano de conteudo').item.json;
if(validated.content_validation?.accepted===false)throw new Error('EDITORIAL_REVIEW_REQUIRED: seleção não aprovada pelos guards de conteúdo.');
const plan=validated.content_plan;
const review=response.review;
if(!review||typeof review.reason!=='string'||!Array.isArray(review.clip_reviews)||review.clip_reviews.length!==plan.clips.length) throw new Error('Revisão individual dos recortes ausente.');
const contexts=validated.editorial_context;
const allowedIds=new Set(contexts.flatMap(c=>[...c.selected_segments,...(c.preceding_segments??[]),...(c.following_segments??[])]).map(s=>s.id));
const frames=$('Preparar evidencias').first().json.frames;
validateDecisionReport(response.decision_report,allowedIds,new Set(frames.map(f=>f.time)),['orientation','framing','composition','transitions','audio','photography','captions','ending','duration']);
if(typeof review.duration_justified!=='boolean'||typeof review.context_preserved!=='boolean') throw new Error('Revisão de duração/contexto ausente.');
const orientationAssessment=$('Exigir previa aprovada').first().json.orientation_assessment;
if(!orientationAssessment||orientationAssessment.status!=='approved') throw new Error('ORIENTATION_REVIEW_REQUIRED: falta prévia visual aprovada.');
let layoutAuditFailure='';
if(response.edit!=null){
 const preferences=$('Normalizar briefing').first().json?.brief?.preferences;
 normalizeArtEdit(preferences,response.edit);
 assertTransformChoices(preferences,response.edit);
 // A missing/incoherent layout audit goes back to the director with the reason (assemble-edit still blocks it).
 try{validateAutomaticLayoutAudit(preferences,response.edit,response.decision_report);}
 catch(e){if(!String(e.message).startsWith('AUTOMATIC_LAYOUT_AUDIT_REQUIRED'))throw e;layoutAuditFailure=e.message;}
 const orientation=response.edit.orientation;
 if((!orientation||JSON.stringify(Object.fromEntries(Object.entries(orientation).sort()))!==JSON.stringify(Object.fromEntries(Object.entries(orientationAssessment.orientation).sort())))||(response.edit.clips??[]).some(c=>(c.rotation??0)!==0)) throw new Error('ORIENTATION_REVIEW_REQUIRED: arte alterou orientação ou aplicou rotação adicional por clip após a prévia.');
