   if(phrase===tokens.slice(i+n,i+2*n).join(' ')&&phrase===tokens.slice(i+2*n,i+3*n).join(' '))repeated=true;
  }
  if(repeated&&tokens.length/(s.end-s.start)>8)issues.push({code:'IMPLAUSIBLE_REPETITION',segment_id:id,detail:'Repetição consecutiva e densidade acima de oito palavras/s; requer outra evidência ASR.'});
  if(text.length>200)issues.push({code:'CAPTION_SEGMENT_TOO_LONG',segment_id:id,detail:'Segmento acima de 200 caracteres; não dividir tempos proporcionalmente.'});
