   const detail='Segmentos se sobrepõem; legenda por segmento exige intervalos sem sobreposição. Preservar timestamps e retranscrever ou selecionar outra fala.';
   issues.push({code:'OVERLAPPING_SEGMENTS',segment_id:id,detail});
   if(previousId!==null)issues.push({code:'OVERLAPPING_SEGMENTS',segment_id:previousId,detail});
  }
