const audit=assessAsr(asr,source.media.duration_seconds);
return [{json:{asr,asr_quality:{attempts:1,selected_attempt:1,initial:audit,selected:audit,source_sha256:source.source_sha256,selection_reason:'Primeira transcrição.'},needs_asr_retry:audit.fatal.length>0||audit.critical_count>0}}];

