const raw=$input.first().json.asr_job_id;
const asr_job_id=typeof raw==='string'?raw.trim().replace(/^"|"$/g,''):'';
if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(asr_job_id))throw new Error('Windmill não retornou job válido de preparo do áudio.');
return [{json:{asr_job_id,asr_job_url:'https://wll.miabuilder.com/run/'+asr_job_id+'?workspace=mia-micro-servicos'}}];

const job=$input.first().json;
const ctx=$('Identificar job de audio').first().json;
const attempt=$runIndex+1;
const max=$('Entrada de teste').first().json.poll.max_attempts;
const completed=job.type==='CompletedJob'||job.completed_at!=null||typeof job.success==='boolean';
// The engine's own code ([CODE] detail) reaches P2 first; generic code only when there is none (e.g. canceled).
const engine=/^\[([A-Z][A-Z0-9_]+)\]\s*([\s\S]*)$/.exec(String(job.result?.error?.message??''));
if(job.canceled||job.is_canceled||(completed&&job.success!==true))throw new Error(engine?engine[1]+': '+engine[2]+' '+ctx.asr_job_url:'ASR_AUDIO_FAILED: preparo falhou ou foi cancelado. '+ctx.asr_job_url);
if(!completed&&attempt>=max)throw new Error('ASR_AUDIO_TIMEOUT: job pode continuar no Windmill; não reenviar automaticamente. '+ctx.asr_job_url);
return [{json:{...ctx,completed,attempt}}];

// BEGIN shared ASR pieces: long audio is transcribed in pieces cut at pauses by the engine (asr_pieces).
// Each piece becomes one item (one ASR call); the responses are joined by adding each piece's exact start.
function asrPieceItems(evidence, base){
 const pieces=evidence?.input_audio_chunks,duration=evidence?.media?.duration_seconds??evidence?.duration_seconds;
 if(!Array.isArray(pieces)||!pieces.length||!Number.isFinite(duration))throw new Error('ASR_AUDIO_INVALID: áudio da transcrição ausente.');
 let end=0;
 for(const [i,p] of pieces.entries()){
  if(p.index!==i||p.format!=='mp3'||typeof p.data!=='string'||!p.data.length||p.data.length>7*1024*1024||!Number.isFinite(p.start_seconds)||!Number.isFinite(p.end_seconds)||Math.abs(p.start_seconds-end)>0.0015||p.end_seconds<=p.start_seconds)
   throw new Error('ASR_AUDIO_INVALID: trechos da transcrição fora de ordem ou incompletos.');
  end=p.end_seconds;
 }
 if(Math.abs(end-duration)>0.05)throw new Error('ASR_AUDIO_INVALID: os trechos não cobrem o áudio inteiro.');
 const {input_audio_chunks,...rest}=base??{};
 return pieces.map(p=>({json:{...rest,input_audio:{format:p.format,data:p.data},
  asr_piece:{index:p.index,count:pieces.length,start_seconds:p.start_seconds,end_seconds:p.end_seconds,cut_in_pause:p.cut_in_pause}}}));
}
function joinAsrPieces(responses, pieces){
 // Same shape as one verbose_json answer, in the evidence's own time basis.
 if(responses.length!==pieces.length)return {error:'ASR_PIECES_MISMATCH: '+responses.length+' respostas para '+pieces.length+' trechos'};
 const segments=[],words=[],texts=[],dropped=responses.map(()=>0);
 for(const [i,raw] of responses.entries()){
  const p=pieces[i],length=p.end_seconds-p.start_seconds;
  if(!raw||raw.error||!Array.isArray(raw.segments)||!Array.isArray(raw.words))return {error:'ASR_PIECE_INVALID: trecho '+i+(raw?.error?' ('+JSON.stringify(raw.error).slice(0,200)+')':'')};
  // Times past the piece are MP3 padding of that piece: clamp, never move them into the next piece.
  const at=t=>Number.isFinite(t)?p.start_seconds+Math.min(Math.max(t,0),length):t;
  // The provider sometimes returns a segment with no text and no duration (n8n 995005: two at the end of a piece).
  // It carries no speech and no time, so it is dropped and counted; every other segment is kept as returned.
  for(const s of raw.segments){
   if(!String(s?.text??'').trim()&&Number.isFinite(s?.start)&&Number.isFinite(s?.end)&&s.end<=s.start){dropped[i]++;continue;}
   segments.push({...s,start:at(s.start),end:at(s.end)});
  }
  for(const w of raw.words)words.push({...w,start:at(w.start),end:at(w.end)});
  if(typeof raw.text==='string'&&raw.text.trim())texts.push(raw.text.trim());
 }
 return {text:texts.join(' '),segments:segments.map((s,id)=>({...s,id})),words,
  pieces:pieces.map((p,i)=>({index:p.index,start_seconds:p.start_seconds,end_seconds:p.end_seconds,cut_in_pause:p.cut_in_pause,segments:responses[i].segments.length-dropped[i],...(dropped[i]?{empty_segments_dropped:dropped[i]}:{})}))};
}
// END shared ASR pieces
const result=$input.first().json;
const source=$('Preparar evidencias').first().json.source_sha256;
if(result.kind!=='audio_evidence'||result.source_sha256!==source||result.timing_basis!=='source')throw new Error('ASR_AUDIO_INVALID: áudio ausente ou fonte divergente.');
// One item per piece (one retranscription call each); every item keeps the evidence binding.
return asrPieceItems(result,result);

